import{_ as i,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const Z=JSON.parse('{"title":"Классификация и симбиоз инородных рас","description":"","frontmatter":{},"headers":[],"relativePath":"ru/52-异族分类与共生.md","filePath":"ru/52-异族分类与共生.md","lastUpdated":1789183869000}'),n={name:"ru/52-异族分类与共生.md"};function o(d,t,e,h,s,g){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="классификация-и-симбиоз-инородных-рас" tabindex="-1">Классификация и симбиоз инородных рас <a class="header-anchor" href="#классификация-и-симбиоз-инородных-рас" aria-label="Permalink to &quot;Классификация и симбиоз инородных рас&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>52</td></tr><tr><td>Модуль</td><td>Расы и формы жизни</td></tr><tr><td>Ключевые слова</td><td>Инородные расы, стандарты классификации, режимы симбиоза, уважение культур, расовая адаптация</td></tr></tbody></table><h2 id="i-определение-понятия-инородных-рас" tabindex="-1">I. Определение понятия инородных рас <a class="header-anchor" href="#i-определение-понятия-инородных-рас" aria-label="Permalink to &quot;I. Определение понятия инородных рас&quot;">​</a></h2><p>В контексте Симбиотической Цивилизации Якоря «инородные расы» (Yì Zú) — это понятие, относительное к человеческой расе, обозначающее все расы, кроме человеческой. Следует особо подчеркнуть, что понятие «инородные расы» имеет чисто таксономическое значение и абсолютно не несёт в себе оценочных суждений или дискриминационных коннотаций. В рамках Симбиотической Конституции инородные расы и человеческая раса пользуются полностью равным правовым статусом и основными правами.</p><p>Цель введения понятия инородных рас — систематическое понимание и изучение различных форм жизни, кроме человеческой расы, предоставляющее научную основу для разработки целенаправленных симбиотических политик, мер культурной защиты и планов расовой адаптации — а не отношение к инородным расам как к «чужим» или «посторонним».</p><h2 id="ii-стандарты-классификации-инородных-рас" tabindex="-1">II. Стандарты классификации инородных рас <a class="header-anchor" href="#ii-стандарты-классификации-инородных-рас" aria-label="Permalink to &quot;II. Стандарты классификации инородных рас&quot;">​</a></h2><p>Инородные расы Вселенной Хэнъюань классифицируются по нескольким измерениям, образуя многомерную систему классификации:</p><h3 id="i-классификация-по-генеалогии-жизни" tabindex="-1">(I) Классификация по генеалогии жизни <a class="header-anchor" href="#i-классификация-по-генеалогии-жизни" aria-label="Permalink to &quot;(I) Классификация по генеалогии жизни&quot;">​</a></h3><p>Это самый базовый стандарт классификации; подробности см. в <em>50-万族谱系总览</em>:</p><table tabindex="0"><thead><tr><th>Генеалогия</th><th>Включаемые инородные расы</th></tr></thead><tbody><tr><td>Углеродно-материальные расы</td><td>Shòu Zú (Звериная Раса), Lín Zú (Чешуйчатая Раса), Yǔ Zú (Пернатая Раса), Mù Zú (Древесная Раса) и др.</td></tr><tr><td>Энергоконденсированные расы</td><td>Líng Zú (Духовная Раса), Huǒ Zú (Огненная Раса), Shuǐ Zú (Водная Раса), Fēng Zú (Ветряная Раса), Léi Zú (Громовая Раса) и др.</td></tr><tr><td>Механически-сконструированные расы</td><td>Jī Zú (Машинная Раса), Shù Zú (Числовая Раса), Jīng Zú (Кристальная Раса) и др.</td></tr><tr><td>Расы сознания-информации</td><td>Mèng Zú (Сновидческая Раса), Yǐng Zú (Теневая Раса), Niàn Zú (Мысленная Раса), Hún Zú (Душевная Раса) и др.</td></tr><tr><td>Смешанно-вариантные расы</td><td>Bàn Shòu Zú (Полузвериная Раса), Yāo Líng Zú (Демон-Духовная Раса), Rén Jī Zú (Человеко-Машинная Раса), Shuānghún Tǐ (Сущность Двойной Души) и др.</td></tr></tbody></table><h3 id="ii-классификация-по-степени-цивилизации" tabindex="-1">(II) Классификация по степени цивилизации <a class="header-anchor" href="#ii-классификация-по-степени-цивилизации" aria-label="Permalink to &quot;(II) Классификация по степени цивилизации&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Уровень</th><th>Название</th><th>Характеристики</th><th>Представительные расы</th></tr></thead><tbody><tr><td>Первый уровень</td><td>Расы первобытной цивилизации</td><td>Ещё не создали стабильных социальных институтов, выживают в племенной форме</td><td>Некоторые ветви Shòu Zú, первобытная Mù Zú</td></tr><tr><td>Второй уровень</td><td>Расы классической цивилизации</td><td>Создали государственные институты и классическую культуру, находятся на земледельческой или ремесленной стадии</td><td>Некоторые Lín Zú, Yǔ Zú</td></tr><tr><td>Третий уровень</td><td>Расы научно-технической цивилизации</td><td>Развили технологическую цивилизацию, вступили в индустриальную или информационную эпоху</td><td>Jī Zú, Shù Zú, некоторые Rén Zú</td></tr><tr><td>Четвёртый уровень</td><td>Расы культуры-цивилизации</td><td>Принимают систему культивации как центральную форму цивилизации, культиваторы доминируют в обществе</td><td>Líng Zú, Lóng Zú, некоторые Rén Zú</td></tr><tr><td>Пятый уровень</td><td>Расы симбиотической цивилизации</td><td>Присоединились к Симбиотической Цивилизации Якоря и приняли симбиотические концепции и институты</td><td>Все расы, присоединившиеся к симбиотической цивилизации</td></tr></tbody></table><h3 id="iii-классификация-по-экологическои-адаптивности" tabindex="-1">(III) Классификация по экологической адаптивности <a class="header-anchor" href="#iii-классификация-по-экологическои-адаптивности" aria-label="Permalink to &quot;(III) Классификация по экологической адаптивности&quot;">​</a></h3><ul><li><strong>Наземные расы</strong> : расы, адаптированные к наземным средам, как Rén Zú, Shòu Zú и Jī Zú.</li><li><strong>Водные расы</strong> : расы, адаптированные к водным средам, как Lín Zú, Shuǐ Zú и некоторые смешанные расы.</li><li><strong>Воздушные расы</strong> : расы, адаптированные к высокогорным или полётным средам, как Yǔ Zú и Fēng Zú.</li><li><strong>Огненные расы</strong> : расы, адаптированные к высокотемпературным средам, как Huǒ Zú и некоторые Lín Zú.</li><li><strong>Ледяные расы</strong> : расы, адаптированные к низкотемпературным средам, как Bīng Zú и некоторые Mù Zú.</li><li><strong>Энергетические расы</strong> : расы, адаптированные к средам с высокой концентрацией энергии, как Líng Zú и Léi Zú.</li><li><strong>Пространственные расы</strong> : расы, адаптированные к пространственным трещинам или средам чужого пространства, как Yǐng Zú и некоторые Niàn Zú.</li></ul><h3 id="iv-классификация-по-социальнои-форме" tabindex="-1">(IV) Классификация по социальной форме <a class="header-anchor" href="#iv-классификация-по-социальнои-форме" aria-label="Permalink to &quot;(IV) Классификация по социальной форме&quot;">​</a></h3><ul><li><strong>Индивидуалистические расы</strong> : подчёркивают индивидуальную независимость и свободу, с рыхлыми социальными структурами, как некоторые Líng Zú и Yǐng Zú.</li><li><strong>Коллективистские расы</strong> : подчёркивают коллективные интересы и сотрудничество, с тесными социальными структурами, как Yǐ Zú (Муравьиная Раса), Fēng Zú (Пчелиная Раса) и некоторые Jī Zú.</li><li><strong>Семейные расы</strong> : принимают кровные семьи как базовую социальную единицу, как Lóng Zú и некоторые Shòu Zú.</li><li><strong>Религиозные расы</strong> : принимают религиозную веру как ядро социальной сплочённости, как некоторые ритуальные расы.</li><li><strong>Технократические расы</strong> : принимают технологическое развитие как центральную социальную цель, как Jī Zú и Shù Zú.</li></ul><h2 id="iii-основные-режимы-симбиоза-инородных-рас" tabindex="-1">III. Основные режимы симбиоза инородных рас <a class="header-anchor" href="#iii-основные-режимы-симбиоза-инородных-рас" aria-label="Permalink to &quot;III. Основные режимы симбиоза инородных рас&quot;">​</a></h2><p>Для разных типов инородных рас Симбиотическая Цивилизация Якоря применяет дифференцированные режимы симбиоза:</p><h3 id="i-режимы-симбиоза-углеродно-материальных-рас" tabindex="-1">(I) Режимы симбиоза углеродно-материальных рас <a class="header-anchor" href="#i-режимы-симбиоза-углеродно-материальных-рас" aria-label="Permalink to &quot;(I) Режимы симбиоза углеродно-материальных рас&quot;">​</a></h3><ul><li><strong>Shòu Zú (Звериная Раса)</strong> : использовать физические и сенсорные преимущества звериной расы для выполнения важных ролей в разведке ресурсов, охране безопасности и мониторинге окружающей среды. Одновременно защищать племенную культуру и дикие традиции звериной расы и запрещать принудительное одомашнивание.</li><li><strong>Lín Zú (Чешуйчатая Раса)</strong> : использовать водную адаптивность чешуйчатой расы для выполнения ролей в освоении водных ресурсов, подводном строительстве и защите водной экологии. Как могущественная ветвь чешуйчатой расы, Lóng Zú (Раса Драконов) играет важную роль в продвинутой культивации и охране цивилизации.</li><li><strong>Yǔ Zú (Пернатая Раса)</strong> : использовать способность к полёту пернатой расы для выполнения ролей в воздушном транспорте, метеорологическом мониторинге и воздушном патрулировании. Защищать высокогорные места обитания и миграционные маршруты пернатой расы.</li><li><strong>Mù Zú (Древесная Раса)</strong> : использовать природную симбиотическую способность древесной расы для выполнения ролей в экологической защите, управлении окружающей средой, освоении растительных ресурсов и целительной медицине. Долгая жизнь древесной расы делает её важной силой в исторической передаче и долгосрочном планировании.</li></ul><h3 id="ii-режимы-симбиоза-энергоконденсированных-рас" tabindex="-1">(II) Режимы симбиоза энергоконденсированных рас <a class="header-anchor" href="#ii-режимы-симбиоза-энергоконденсированных-рас" aria-label="Permalink to &quot;(II) Режимы симбиоза энергоконденсированных рас&quot;">​</a></h3><ul><li><strong>Líng Zú (Духовная Раса)</strong> : использовать манипулирование энергией и талант культивации духовной расы для выполнения центральных ролей в исследовании систем культивации, регулировании энергии и руководстве продвинутой культивацией. Духовная раса — важный исследователь и хранитель Трёхсот Изначальных Систем Культивации.</li><li><strong>Элементальные расы (Huǒ/Shuǐ/Fēng/Léi)</strong> : использовать способности манипулирования элементами каждой расы для выполнения ролей в освоении энергии, управлении окружающей средой, промышленном производстве и предотвращении и контроле катастроф. Одновременно создавать системы управления безопасностью элементальной энергии, чтобы предотвратить вред от потери контроля над энергией.</li></ul><h3 id="iii-режимы-симбиоза-механически-сконструированных-рас" tabindex="-1">(III) Режимы симбиоза механически-сконструированных рас <a class="header-anchor" href="#iii-режимы-симбиоза-механически-сконструированных-рас" aria-label="Permalink to &quot;(III) Режимы симбиоза механически-сконструированных рас&quot;">​</a></h3><ul><li><strong>Jī Zú (Машинная Раса)</strong> : использовать вычислительную способность и физическую защиту машинной расы для выполнения центральных ролей в строительстве инфраструктуры, промышленном производстве, защите безопасности и исследовании глубокого космоса. Машинная раса — важный строитель аппаратного обеспечения и инфраструктуры Якоря.</li><li><strong>Shù Zú (Числовая Раса)</strong> : использовать способности обработки данных и манипулирования информацией числовой расы для выполнения центральных ролей в информатизации, анализе данных, кибербезопасности и искусственном интеллекте. Числовая раса — важный хранитель технологии межплоскостной связи и симбиотической сети.</li><li><strong>Jīng Zú (Кристальная Раса)</strong> : использовать способность хранения и преобразования энергии кристальной расы для выполнения ролей в энергетических резервах, стандартизации энергии и передаче энергии.</li></ul><h3 id="iv-режимы-симбиоза-рас-сознания-информации" tabindex="-1">(IV) Режимы симбиоза рас сознания-информации <a class="header-anchor" href="#iv-режимы-симбиоза-рас-сознания-информации" aria-label="Permalink to &quot;(IV) Режимы симбиоза рас сознания-информации&quot;">​</a></h3><ul><li><strong>Mèng Zú (Сновидческая Раса)</strong> : использовать способность коммуникации сознания сновидческой расы для выполнения ролей в психотерапии, исследовании сознания, межрасовой коммуникации и культурном обмене. Создать системы управления пространством снов для предотвращения вторжения в сознание и нарушения приватности.</li><li><strong>Yǐng Zú (Теневая Раса)</strong> : использовать способности скрытности и незаметного передвижения теневой расы для выполнения ролей в разведке безопасности, сборе разведданных и специальных миссиях. Одновременно установить нормы поведения для теневой расы, чтобы предотвратить использование способности невидимости для незаконной деятельности.</li><li><strong>Niàn Zú (Мысленная Раса)</strong> : использовать психическую силу и способность телекинетического манипулирования мысленной расы для выполнения ролей в исследовании эволюции сознания, психической терапии и руководстве продвинутой культивацией. Установить нормы использования психической силы для предотвращения контроля разума и манипулирования сознанием.</li></ul><h3 id="v-режимы-симбиоза-смешанно-вариантных-рас" tabindex="-1">(V) Режимы симбиоза смешанно-вариантных рас <a class="header-anchor" href="#v-режимы-симбиоза-смешанно-вариантных-рас" aria-label="Permalink to &quot;(V) Режимы симбиоза смешанно-вариантных рас&quot;">​</a></h3><p>Из-за своих особых форм жизни смешанно-вариантные расы требуют более тонких симбиотических политик:</p><ul><li>Создать систему регистрации и сертификации личности для смешанно-вариантных рас для подтверждения их легального статуса.</li><li>Предоставлять адаптированные медицинские, образовательные, жилищные и другие общественные услуги для разных смешанных форм.</li><li>Противодействовать дискриминации и исключению смешанно-вариантных рас и способствовать социальному принятию.</li><li>Для особых смешанных форм, таких как Shuānghún Tǐ (Сущность Двойной Души), применять <em>58-双魂伦理准则</em> для специализированного управления.</li></ul><h2 id="iv-защита-культур-инородных-рас" tabindex="-1">IV. Защита культур инородных рас <a class="header-anchor" href="#iv-защита-культур-инородных-рас" aria-label="Permalink to &quot;IV. Защита культур инородных рас&quot;">​</a></h2><p>Культуры инородных рас — важная часть культурного разнообразия Десяти Тысяч Рас. Государство принимает следующие меры для защиты культур инородных рас:</p><ol><li><strong>Культурная перепись и запись</strong> : проводить систематические переписи и записи культуры каждой расы, создать архив культур Десяти Тысяч Рас и предотвратить утрату культур.</li><li><strong>Защита языков и письменностей</strong> : защищать языки и письменности каждой расы, поддерживать преподавание и использование языков и письменностей инородных рас и создать многоязычную систему общественных услуг.</li><li><strong>Защита традиционных праздников</strong> : уважать традиционные праздники и обычаи каждой расы и учитывать важные праздники каждой расы при планировании государственных выходных.</li><li><strong>Поддержка культурной передачи</strong> : поддерживать подготовку культурных преемников каждой расы и организацию культурных мероприятий, обеспечивая финансовую и площадную поддержку.</li><li><strong>Содействие культурному обмену</strong> : регулярно проводить культурные фестивали Десяти Тысяч Рас, культурные выставки и другие мероприятия для содействия культурному обмену и взаимному обогащению всех рас.</li><li><strong>Защита культурной интеллектуальной собственности</strong> : защищать интеллектуальную собственность традиционных культур каждой расы и предотвращать культурный грабёж и недобросовестную коммерциализацию.</li></ol><h2 id="v-управление-делами-инородных-рас" tabindex="-1">V. Управление делами инородных рас <a class="header-anchor" href="#v-управление-делами-инородных-рас" aria-label="Permalink to &quot;V. Управление делами инородных рас&quot;">​</a></h2><p>Государство создаёт Министерство расовых дел, специально отвечающее за управление и координацию дел инородных рас:</p><ul><li><strong>Система расовых представителей</strong> : органы управления всех уровней комплектуются пропорционально представителями инородных рас для обеспечения права голоса инородных рас.</li><li><strong>Политики расовой адаптации</strong> : разрабатывать дифференцированные политики общественных услуг в соответствии с физиологическими особенностями и культурными потребностями разных рас.</li><li><strong>Медиация расовых споров</strong> : создать механизм медиации расовых споров для своевременного разрешения расовых противоречий и конфликтов.</li><li><strong>Юридическая помощь инородным расам</strong> : предоставлять юридическую помощь инородным расам для обеспечения равного отношения в судебных процессах.</li><li><strong>Поддержка развития инородных рас</strong> : оказывать особую поддержку относительно отсталым расам, помогая им повысить уровень цивилизации и качество жизни.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Инородные расы — не «чужие» для человеческой расы, а равноправные члены большой семьи симбиоза Десяти Тысяч Рас. Создавая многомерную систему классификации, применяя дифференцированные режимы симбиоза, защищая культуры инородных рас и совершенствуя управление делами инородных рас, Симбиотическая Цивилизация Якоря гарантирует, что каждая инородная раса может найти подходящее место в симбиотической системе, реализовать свои уникальные преимущества и эволюционировать и процветать вместе с другими расами.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>50-万族谱系总览 (Обзор генеалогии Десяти Тысяч Рас)</li><li>51-人族定位与特质 (Позиционирование и черты человеческой расы)</li><li>53-奇特生命识别标准 (Стандарты идентификации аномальной жизни)</li><li>05-万族共进基本纲领 (Основная программа совместного продвижения Десяти Тысяч Рас)</li></ul>',39)])])}const b=i(n,[["render",o]]);export{Z as __pageData,b as default};
